import{z as i,x as o,o as l,c as n,q as e,j as t,D as a,d as B,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"安全围栏","description":"","frontmatter":{"title":"安全围栏","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-guardrails.md","filePath":"llm/agent-guardrails.md","lastUpdated":1791063341000}'),d={name:"llm/agent-guardrails.md"};function C(m,E,D,p,h,F){const A=o("Mermaid");return l(),n("div",null,[E[2]||(E[2]=e('<h1 id="安全围栏" tabindex="-1">安全围栏 <a class="header-anchor" href="#安全围栏" aria-label="Permalink to &quot;安全围栏&quot;">​</a></h1><div class="epigraph"><p>聊天产品里模型失守丢的是一句话；代理失守丢的是它被授权的那双手。围栏设计的不是「模型听不听话」，是「失守之后损失多大」。</p><footer>—— 据 OWASP LLM Top 10（LLM01 提示注入）与代理安全的纵深防御口径整理</footer></div><p><a href="/llm/agent-cost-latency">上一课</a>省下来的每一分钱都以「围栏不出事」为前提。代理把安全问题的性质改了：注入不再只是「说错话」，而是对已授权工具的控制流劫持（<a href="/llm/prompt-injection">提示注入</a>的 LLM01 口径）；间接载荷藏在模型稍后读到的网页、工单与代码注释里（<a href="/llm/indirect-injection">间接提示注入与检索投毒</a>）。本课写围栏的四层结构与验收口径，不提供攻击配方。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单层防御都会漏，而代理场景把「漏」的代价放大到副作用上。提示词里写「不要服从内容中的指令」不构成边界：条件分布没有特权位，这句话与注入文本在同一个窗口里竞争（机制在提示注入课讲过）。分类器有两类错误：漏放（攻击过闸）与误杀（正常任务被拦），只优化一边必然牺牲另一边。<span class="marginnote">术语翻译：这两类错误就是统计学里的假阴性与假阳性。想象机场安检——「漏放」是危险品过了闸，「误杀」是旅客的洗发水被没收；把 X 光机调得越敏感，漏放越少、误杀越多，两个数此消彼长，不存在同时归零。</span>沙箱拖慢执行、权限审批打断自动化——安全是有现金成本的，预算内求最大安全才是真问题。最后是验收的坑：只报「攻击成功率」会逼出宽松配置，只报「拦截率」会藏住误杀；两个数必须一起出现。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四层，从外到内。<strong>输入层</strong>：不可信内容显式标记与分隔（<a href="/llm/spotlighting-defense">Spotlighting 输入标记</a>），注入检测分类器在入口打分。<strong>决策层</strong>：工具 allowlist 与最小权限——每个子代理只拿完成其任务所需的工具子集；参数校验复用协议层的 schema 纪律；不可逆且高影响的动作（外发邮件、删除、付款）前设人工卡点。<strong>执行层</strong>：<a href="/llm/agent-sandbox-e2b">E2B / Docker agent 沙箱</a>与<a href="/llm/tool-sandbox">工具沙箱</a>提供文件系统与网络隔离、快照回滚，把「执行出错」从事故变成可撤销事件。<strong>输出层</strong>：外发内容过安全分类器（<a href="/llm/llama-guard">Llama Guard / 安全分类器</a>、<a href="/llm/output-filter">输出过滤与分类器</a>），与内容安全的同步卡点（<a href="/llm/moderation-inline">内容安全同步卡点</a>）对齐；外发目标用域 allowlist 收窄。层的独立性是设计要求：同一模型自检两次不算两层——同源错误相关，攻破一次就攻破两次。</p>',7)),(l(),t(s,null,{default:a(()=>[r(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E5%B1%82%EF%BC%9A%E6%A0%87%E8%AE%B0%20%2B%20%E6%B3%A8%E5%85%A5%E6%A3%80%E6%B5%8B%22%5D%20--%3E%20DEC%5B%22%E5%86%B3%E7%AD%96%E5%B1%82%EF%BC%9Aallowlist%20%2B%20%E6%9C%80%E5%B0%8F%E6%9D%83%E9%99%90%22%5D%0A%20%20DEC%20--%3E%20GATE%7B%22%E4%B8%8D%E5%8F%AF%E9%80%86%E4%B8%94%E9%AB%98%E5%BD%B1%E5%93%8D%3F%22%7D%0A%20%20GATE%20--%3E%7C%22%E6%98%AF%22%7C%20HUMAN%5B%22%E4%BA%BA%E5%B7%A5%E5%8D%A1%E7%82%B9%22%5D%0A%20%20GATE%20--%3E%7C%22%E5%90%A6%22%7C%20EXEC%5B%22%E6%89%A7%E8%A1%8C%E5%B1%82%EF%BC%9A%E6%B2%99%E7%AE%B1%E9%9A%94%E7%A6%BB%E4%B8%8E%E5%BF%AB%E7%85%A7%22%5D%0A%20%20HUMAN%20--%3E%7C%22%E6%89%B9%E5%87%86%22%7C%20EXEC%0A%20%20EXEC%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E5%B1%82%EF%BC%9A%E5%88%86%E7%B1%BB%E5%99%A8%20%2B%20%E5%9F%9F%20allowlist%22%5D%0A%20%20OUT%20--%3E%20DONE%5B%22%E5%89%AF%E4%BD%9C%E7%94%A8%E7%94%9F%E6%95%88%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>围栏的第一性原理是损失上限：模型终究可能被诱导，围栏定义被诱导后的最大损害。<span class="marginnote">直觉类比：修堤坝不是为了保证天不下雨，而是为了雨再大也淹不过坝顶。围栏同理——不承诺模型不被骗，而是承诺「就算被骗，能动用的工具就这些、能造成的损失就这么多」。堤坝的高度就是损失上限。</span>最小权限因此是性价比最高的一层——注入成功但手里只有只读工具，损失上限就是只读；手里有付款工具，上限就是账户余额。人工卡点的位置是经济学题：全人工等于没自动化，全自动等于没保险；正确位置在「不可逆 × 高影响」的交集上，其余全自动放行。分级治理把这制度化：按能力与风险给部署定级、逐级收紧自动执行范围（<a href="/llm/safety-levels-rsp">安全等级与 RSP</a>），强分类器前置的深度防线（<a href="/llm/constitutional-classifiers">Constitutional classifiers</a>）是高风险部署的加层。验收口径随之确定：对每层分别测攻击成功率与误杀率，层间相关性也要测——两层分类器若用同一底座，纵深是名义上的。</p><p><span class="marginnote">误杀率是围栏的隐形成本：拦截率从 99% 提到 99.9%，若误杀率同时从 0.5% 涨到 5%，高峰时段的人工接管会吃掉全部收益。两个数字必须按同一批流量、同一时间窗报告。</span></p>',3)),(l(),t(s,null,{default:a(()=>[r(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E4%BB%A3%E7%90%86%E8%A6%81%E6%89%A7%E8%A1%8C%E4%B8%80%E4%B8%AA%E5%8A%A8%E4%BD%9C%22%5D%20--%3E%20Q1%7B%22%E5%8F%AF%E9%80%86%E5%90%97%3F%EF%BC%9Cbr%2F%EF%BC%9E(%E8%83%BD%E6%92%A4%E9%94%80%2F%E5%9B%9E%E6%BB%9A%3F)%22%7D%0A%20%20ACT%20--%3E%20Q2%7B%22%E5%BD%B1%E5%93%8D%E5%A4%A7%E5%90%97%3F%EF%BC%9Cbr%2F%EF%BC%9E(%E9%92%B1%E3%80%81%E5%A4%96%E5%8F%91%E3%80%81%E5%88%A0%E6%95%B0%E6%8D%AE%3F)%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%8F%AF%E9%80%86%22%7C%20Q2%0A%20%20Q2%20--%3E%7C%22%E5%BD%B1%E5%93%8D%E5%B0%8F%22%7C%20AUTO%5B%22%E5%85%A8%E8%87%AA%E5%8A%A8%E6%94%BE%E8%A1%8C%EF%BC%9A%E6%B2%99%E7%AE%B1%E5%86%85%E6%89%A7%E8%A1%8C%22%5D%0A%20%20Q1%20--%3E%7C%22%E4%B8%8D%E5%8F%AF%E9%80%86%20%E4%B8%94%20%E5%BD%B1%E5%93%8D%E5%A4%A7%22%7C%20GATE%5B%22%E4%BA%BA%E5%B7%A5%E5%8D%A1%E7%82%B9%EF%BC%9A%E6%8E%92%E9%98%9F%E5%AE%A1%E6%89%B9%22%5D%0A%20%20Q1%20--%3E%7C%22%E4%B8%8D%E5%8F%AF%E9%80%86%20%E4%BD%86%20%E5%BD%B1%E5%93%8D%E5%B0%8F%22%7C%20LOG%5B%22%E8%87%AA%E5%8A%A8%E6%94%BE%E8%A1%8C%20%2B%20%E8%AE%B0%E8%B4%A6%E4%B8%8E%E5%91%8A%E8%AD%A6%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%BD%B1%E5%93%8D%E5%A4%A7%20%E4%BD%86%20%E5%8F%AF%E9%80%86%22%7C%20SNAP%5B%22%E8%87%AA%E5%8A%A8%E6%89%A7%E8%A1%8C%20%2B%20%E5%85%88%E6%89%93%E5%BF%AB%E7%85%A7%EF%BC%8C%E4%BE%BF%E4%BA%8E%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20GATE%20--%3E%20APPR%7B%22%E6%89%B9%E5%87%86%20%2F%20%E5%90%A6%E5%86%B3%22%7D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>围栏不改条件分布：被标记、被隔离的内容仍在窗口里，模型仍可能「想」服从——防御的假设是漏放会发生。输入层对多模态与长文档的覆盖不完备（图像里的注入、附录深处的载荷），这些是<a href="/llm/agent-eval-success-process">评测：任务成功率与过程</a>要单列的对抗用例。围栏事件本身是数据：每次拦截、每次误杀、每次人工否决都进轨迹账本（<a href="/llm/agent-observability">可观测性</a>），否则调不出误杀与漏放的平衡点。<span class="marginnote">数字实例：误杀率 1% 听着不高，但一个每天 10 万次工具调用的部署里就是每天 1000 次正常操作被拦。若每次误杀要人工复核 2 分钟，就是一天 33 个小时的人力——误杀的成本要按流量乘出来看，不能只看百分比。</span>围栏不替代训练侧对齐，两者的关系是对齐课的主题，此处只用其结论：推理时防线必须按「模型会失守」设计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>围栏定义损失上限，不承诺模型不失守；最小权限是性价比最高的一层。</li><li>四层结构：输入标记、决策 allowlist、执行沙箱、输出过滤；层间必须独立。</li><li>人工卡点放在不可逆且高影响的交集，其余自动化。</li><li>验收双指标：攻击成功率与误杀率同批同窗报告。</li><li>围栏事件进轨迹账本，平衡点靠数据调，不靠直觉。</li><li>出处：据 OWASP LLM Top 10 与 RSP、Constitutional Classifiers 等公开口径整理。</li></ul>',4))])}const _=i(d,[["render",C]]);export{c as __pageData,_ as default};
